fn replace_blanks_with_chars(str1: &Vec<char>, ch: char) -> Vec<char> {
    let mut out = Vec::with_capacity(str1.len());
    for &c in str1.iter() {
        if c == ' ' {
            out.push(ch);
        } else {
            out.push(c);
        }
    }
    out
}

